import sys
from collections import Counter

def find_substring_brute(s, words):
    if not s or not words:
        return []
    n, m = len(s), len(words)
    L = len(words[0])
    total = m * L
    need = Counter(words)
    res = []
    for i in range(n - total + 1):
        cnt = need.copy()
        ok = True
        for j in range(i, i + total, L):
            w = s[j:j + L]
            if cnt.get(w, 0) > 0:
                cnt[w] -= 1
            else:
                ok = False
                break
        if ok:
            res.append(i)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    res = find_substring_brute(s, words)
    if res:
        print(' '.join(map(str, res)))
    else:
        print()

import sys
from collections import Counter

def find_substring_opt(s, words):
    if not s or not words:
        return []
    n, m = len(s), len(words)
    L = len(words[0])
    total = m * L
    if n < total:
        return []
    need = Counter(words)
    res = []
    for off in range(L):
        left = off
        cnt = {}
        matched = 0
        for right in range(off, n - L + 1, L):
            w = s[right:right + L]
            if w in need:
                cnt[w] = cnt.get(w, 0) + 1
                if cnt[w] == need[w]:
                    matched += 1
                while cnt[w] > need[w]:
                    lw = s[left:left + L]
                    if cnt[lw] == need[lw]:
                        matched -= 1
                    cnt[lw] -= 1
                    left += L
                if matched == len(need):
                    res.append(left)
                    lw = s[left:left + L]
                    if cnt[lw] == need[lw]:
                        matched -= 1
                    cnt[lw] -= 1
                    left += L
            else:
                cnt.clear()
                matched = 0
                left = right + L
    res.sort()
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    res = find_substring_opt(s, words)
    if res:
        print(' '.join(map(str, res)))
    else:
        print()

import sys
from collections import Counter

def find_substring_best(s, words):
    if not s or not words:
        return []
    n, m = len(s), len(words)
    L = len(words[0])
    total = m * L
    need = Counter(words)
    res = []
    for off in range(L):
        cnt = {}
        left = off
        for right in range(off, n - L + 1, L):
            w = s[right:right + L]
            if w not in need:
                cnt.clear()
                left = right + L
                continue
            cnt[w] = cnt.get(w, 0) + 1
            while cnt[w] > need[w]:
                lw = s[left:left + L]
                cnt[lw] -= 1
                if cnt[lw] == 0:
                    del cnt[lw]
                left += L
            if right - left + L == total:
                res.append(left)
    res.sort()
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    res = find_substring_best(s, words)
    if res:
        print(' '.join(map(str, res)))
    else:
        print()
